<template><section class="page"><div class="page-title"><div><h1>设备管理</h1><p class="muted">设备身份、网络、健康状态和维护操作</p></div><span class="online">● {{online?'设备在线':'连接失败'}}</span></div><div class="cards"><article><h2>设备身份</h2><label>设备名称<input v-model="form.device_name"></label><label>设备编号<input v-model="form.device_id"></label><label>工位编号<input v-model="form.station_id"></label><label>主机名<input v-model="form.hostname"></label><button @click="saveIdentity" :disabled="saving">{{saving?'保存中…':'保存身份'}}</button></article><article class="wide"><h2>网络配置</h2><div class="tabs"><button :class="{active:tab==='ethernet'}" @click="tab='ethernet'">有线网络</button><button :class="{active:tab==='wifi'}" @click="tab='wifi'">Wi‑Fi</button></div><div class="form-grid"><label>地址模式<select v-model="network.mode"><option value="dhcp">DHCP 自动获取</option><option value="static">静态 IP</option></select></label><label>网卡<input v-model="network.interface"></label><label>静态 IP<input v-model="network.static_ip"></label><label>子网掩码<input v-model="network.netmask"></label><label>网关<input v-model="network.gateway"></label><label>DNS<input v-model="network.dns"></label><label v-if="tab==='wifi'">Wi‑Fi SSID<input v-model="network.wifi_ssid"></label><label v-if="tab==='wifi'">Wi‑Fi 密码<input v-model="network.wifi_password" type="password"></label></div><p class="hint">当前 IP：{{network.ip||'--'}}　MAC：{{network.mac||'--'}}　链路：{{network.link_speed||'--'}}</p><button @click="saveNetwork">保存并应用网络</button><button class="ghost" @click="testNetwork" :disabled="testing">{{testing?'测试中…':'网络连通性测试'}}</button></article><article><h2>设备健康</h2><p>CPU 温度：<strong>{{health.cpu_temperature_c||'--'}} °C</strong></p><p>磁盘：<strong>{{overview.storage?.used_gb}} / {{overview.storage?.total_gb}} GB</strong></p><p>服务：<strong>{{overview.services?.backend||'--'}}</strong></p></article><article><h2>声光报警器</h2><p>状态：<strong>{{overview.peripherals?.alarm_light?.connected?'已连接':'未连接'}}</strong></p><p>路径：<code>/dev/ch341-light</code></p><p>波特率：<strong>9600（固定）</strong></p><button @click="alarmTest">测试报警器</button></article><article class="wide"><h2>维护操作</h2><button @click="backup">导出配置备份</button><button @click="restore">恢复最近备份</button><button @click="clearLogs">清理缓存和日志</button><button class="danger" @click="factoryReset">恢复出厂设置</button><p class="hint">{{message}}</p></article></div></section></template><script setup>import {ref,onMounted} from 'vue';import {request,put,post} from '../api';const form=ref({}),network=ref({}),overview=ref({}),health=ref({}),message=ref(''),saving=ref(false),testing=ref(false),online=ref(false),tab=ref('ethernet');const load=async()=>{try{overview.value=await request('/api/device/overview');form.value={...overview.value.identity};network.value={...overview.value.network};health.value=await request('/api/device/health');online.value=true}catch(e){online.value=false}};const saveIdentity=async()=>{saving.value=true;try{await put('/api/device/identity',form.value);message.value='身份已保存，工作台将在数秒内同步';await load()}catch(e){message.value=e.message}finally{saving.value=false}};const saveNetwork=async()=>{try{await put('/api/network',network.value);message.value='网络配置已保存'}catch(e){message.value=e.message}};const testNetwork=async()=>{testing.value=true;try{const p=await post('/api/network/test');message.value=`${p.message}，延时：${p.latency_ms} ms`}catch(e){message.value=e.message}finally{testing.value=false}};const alarmTest=async()=>{const p=await post('/api/peripherals/alarm-light/test');message.value=p.message};const backup=async()=>{const p=await post('/api/config/backup');const f=p.file.split('/').pop();const a=document.createElement('a');a.href=location.origin+'/api/config/backups/'+encodeURIComponent(f);a.download=f;a.click();message.value=`备份已下载：${f}`};const restore=async()=>{if(confirm('确认恢复最近备份？'))message.value=(await post('/api/config/restore')).message};const clearLogs=async()=>{if(confirm('确认清理日志？'))message.value=(await post('/api/system/clear-logs')).message};const factoryReset=async()=>{if(prompt('管理员密码（开发环境：admin）')==='admin'&&confirm('确认恢复出厂设置？'))message.value=(await post('/api/system/factory-reset',{confirm:true,password:'admin'})).message};onMounted(load)</script>
